static void Parse_NumberValue(char *string, int subtype, unsigned long int *intvalue,
                              double *floatvalue)
{
  unsigned long int dotfound = 0;

  *intvalue = 0;
  *floatvalue = 0;

  if (subtype & 0x0800)
  {
    while(*string)
    {
      if (*string == '.')
      {
        if (dotfound) return;
        dotfound = 10;
        string++;
      }
      if (dotfound)
      {
        *floatvalue = *floatvalue + (double) (*string - '0') /
