  }
  else if (subtype & 0x0008)
  {
    while(*string) *intvalue = *intvalue * 10 + (*string++ - '0');
    *floatvalue = *intvalue;
  }
  else if (subtype & 0x0100)
  {

    string += 2;
    while(*string)
    {
      *intvalue <<= 4;
