   int octet_count;
   int bits_count;
   int i;

   ret = 0;

   ch = (unsigned char) *ptr++;

   if ((ch & 0x80) == 0x00){
      if (result)
  *result = ch;
   }else{
      if ((ch & 0xE0) == 0xC0){
  octet_count = 2;
  ch &= ~0xE0;
