      }else if ((ch & 0xFE) == 0xFC){
  octet_count = 6;
  ch &= ~0xFE;
      }else{
  return NULL;
      }

      bits_count = (octet_count-1) * 6;
      ret |= (ch << bits_count);
      for (i=1; i < octet_count; ++i){
  bits_count -= 6;

